class LoginManagement(object):
    """
    The class corresponding to login management page on selenium_coam web, all operations
    will be implemented or added in its corresponding classes.
    """
    def __init__(self, page_dict):
        self._coam_login_management = page_dict['coam_login_management']
        self._lab_access_login_management = page_dict['lab_access_login_management']

    @property
    def coam_login_management(self):
        return self._coam_login_management

    @property
    def lab_access_login_management(self):
        return self._lab_access_login_management


